def second_smallest(lst):
    if not lst:
        raise ValueError("List must contain at least one element")
    if len(lst) == 1:
        return lst[0]
    smallest = lst[0]
    second = None
    for num in lst[1:]:
        if num < smallest:
            second = smallest
            smallest = num
        elif second is None or num < second:
            second = num
    # If second is None, it means all elements are equal
    if second is None:
        return smallest
    return second
