def is_decimal(s: str) -> bool:
    """
    Return True if the string s represents a decimal number with exactly two digits after the decimal point,
    and False otherwise.
    """
    # Check that there is exactly one decimal point
    if s.count('.') != 1:
        return False

    integer_part, decimal_part = s.split('.', 1)

    # The decimal part must have exactly two digits
    if len(decimal_part) != 2:
        return False

    # The integer part can be empty (e.g., ".12"), or have a sign
    # Validate integer part: can be empty or have optional '+' or '-' followed by digits
    if integer_part in ('', '+', '-'):
        # if empty or just sign, it's allowed as long as decimal is valid digits
        pass
    else:
        # If integer part has sign, check it starts with sign and rest digits
        if integer_part[0] in '+-':
            if not integer_part[1:].isdigit():
                return False
        else:
            if not integer_part.isdigit():
                return False

    # Decimal part must be all digits
    if not decimal_part.isdigit():
        return False

    return True
