def is_Two_Alter(s: str) -> bool:
    # The string must have at least two characters to alternate
    if len(s) < 2:
        return False

    # Extract the two characters to alternate
    first_char = s[0]
    # Find the second distinct character
    second_char = None
    for ch in s:
        if ch != first_char:
            second_char = ch
            break

    # If no second distinct character found, return False
    if second_char is None:
        return False

    # Check that only these two characters appear in the string
    allowed_chars = {first_char, second_char}
    if any(ch not in allowed_chars for ch in s):
        return False

    # Check the string strictly alternates between these two characters
    for i in range(len(s)):
        expected_char = first_char if i % 2 == 0 else second_char
        if s[i] != expected_char:
            return False

    return True
